export const v3MicTokens=['≤0.25','≤0.5','≤1','≥8','≥16','>64','<1','0.5','1','2','4','8','16'];
export const v3DrugNames=['Ampicillin','Ampicillin-sulbactam','Piperacillin-tazobactam','Cefazolin','Cefoxitin','Cefuroxime','Cefotaxime','Ceftazidime','Ceftriaxone','Cefepime','Aztreonam','Ertapenem','Meropenem','Meropenem-vaborbactam','Ceftazidime-avibactam','Ceftolozane-tazobactam','Amikacin','Gentamicin','Tobramycin','Ciprofloxacin','Levofloxacin','Trimethoprim-sulfamethoxazole','Tigecycline'];
const modes=[{id:'normal',fontSize:18},{id:'small',fontSize:10},{id:'blurred',fontSize:18,blurStdDeviation:.4},{id:'phone',fontSize:18,rotationDegrees:1.4,skewDegrees:.8,phonePhotoSimulation:true,glare:true},{id:'contrast',fontSize:18,foreground:'#7f8986',contentOpacity:.7}];
const base={synthetic:true,scientificInterpretationAllowed:false,width:1200,height:810,columnGroups:1,rowHeight:43,foreground:'#102f2b',grid:'#9bb8b1',background:'#ffffff',tags:['v3_additive'],fontSize:18};
export const v3FullRowFixtures=[...modes.map(mode=>({...base,...mode,id:'v3-operators-'+mode.id,rowCount:13,rows:v3MicTokens.map((mic,index)=>({index,label:v3DrugNames[index],mic,category:['S','I','R','SDD','NS'][index%5]}))})),{...base,id:'v3-drugs-23',height:1200,rowCount:23,rows:v3DrugNames.map((label,index)=>({index,label,mic:v3MicTokens[index%13],category:['S','I','R','SDD','NS'][index%5]}))}];
export const v3IsolatedCells=[...modes.flatMap(mode=>v3MicTokens.map((text,i)=>({...mode,id:`mic-${mode.id}-${i}`,field:'mic',text}))),...[10,14,18].flatMap(fontSize=>['S','I','R','SDD','NS','1','l','|',''].map((text,i)=>({id:`category-${fontSize}-${i}`,fontSize,field:'category',text}))),...v3DrugNames.map((text,i)=>({id:`drug-${i}`,fontSize:18,field:'drug',text}))];
const escape=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
export function isolatedCellSvg(f){return `<svg xmlns="http://www.w3.org/2000/svg" width="650" height="80"><defs><filter id="blur"><feGaussianBlur stdDeviation="${f.blurStdDeviation||0}"/></filter></defs><rect width="650" height="80" fill="white"/><g filter="url(#blur)" opacity="${f.contentOpacity||1}" transform="rotate(${f.rotationDegrees||0} 60 40) skewX(${f.skewDegrees||0})"><text x="18" y="48" font-family="Arial, Helvetica, sans-serif" font-size="${f.fontSize}" fill="${f.foreground||'#102f2b'}">${escape(f.text)}</text></g></svg>`;}
